use alloc::borrow::Cow;

use bevy_app::App;

use crate::{ModelApp, ModelInfo};

/// A model nothing is known about, to build the others from.
const UNKNOWN: ModelInfo = ModelInfo {
    name: None,
    provider: None,
    api: None,
    base_url: None,
    reasoning: None,
    input: Cow::Borrowed(&[]),
    context_window: None,
    max_output_tokens: None,
    cost: None,
    thinking_levels: Cow::Borrowed(&[]),
    input_limits: None,
    prompt_cache: None,
    headers: Cow::Borrowed(&[]),
    compat: None,
};

/// Register each (id, info) entry.
fn register(app: &mut App, models: &[(&str, ModelInfo)]) {
    for (id, info) in models {
        app.register_model(*id, info.clone());
    }
}
